package netdiag

import (
	"strings"
	"testing"
)

// pathHelpBody returns the "Path Tab — How it works" paragraph on one line.
func pathHelpBody(t *testing.T) string {
	t.Helper()
	for _, s := range New(testConfig()).GetHelpContent().Sections {
		if s.Title == "Path Tab — How it works" {
			return strings.Join(strings.Fields(s.Body), " ")
		}
	}
	t.Fatal(`no section "Path Tab — How it works"`)
	return ""
}

// DEVDESK-330 step 7, Rule 114: the help says what the container source does,
// what it does not do, and where it stops.
func TestPathHelpExplainsTheContainerSource(t *testing.T) {
	body := pathHelpBody(t)
	cases := []struct{ what, want string }{
		{"the key", "ctrl+o"},
		{"the engine offered", "Docker Engine"},
		{"this machine remains the vantage point", "from this machine"},
		{"the trace row", "trace"},
		{"Docker Desktop is not offered", "Docker Desktop"},
		{"podman is not offered", "podman"},
		{"not offered yet", "not offered"},
		{"no container running", "no running container"},
		{"the engine is only read", "ps, info"},
		{"the inspect read", "inspect"},
		{"nothing is started", "starts nothing"},
		{"a remote engine is not detected", "remote"},
	}
	for _, tc := range cases {
		if !strings.Contains(body, tc.want) {
			t.Errorf("Path help lacks %q (%s)", tc.want, tc.what)
		}
	}
}

