1	package netdiag
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"os"
8		"path/filepath"
9		"slices"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// DEVDESK-330 criterion 7, view level: the Path tab reaches the container
16	// engine only through a fixed list of read functions, and no source file of the
17	// package names a verb that starts, creates or enters a container. The runtime
18	// half is TestPathEngineReadsStartNothing.
19	
20	const (
21		dockerImportPath = "github.com/anthnel/devdesk/internal/docker"
22		engineImportPath = "github.com/anthnel/devdesk/internal/engine"
23	)
24	
25	// allowedDockerUses is every docker.<X> the Path tab may name: the read
26	// functions and the types they return.
27	var allowedDockerUses = []string{
28		"Container", "ContainerNetworking", "EndpointNetwork",
29		"ListContainersContext", "EngineOperatingSystem", "InspectContainerNetworking",
30		"IsContainerID",
31	}
32	
33	// allowedEngineUses is every engine.<X> the Path tab may name.
34	var allowedEngineUses = []string{"Current"}
35	
36	// forbiddenVerbs are engine arguments that change a container or open a shell
37	// in it. A string literal equal to one of them has no business in this package.
38	var forbiddenVerbs = []string{
39		"start", "exec", "run", "cp", "attach", "create", "restart", "unpause",
40		"kill", "stop", "pause", "rm", "commit",
41	}
42	
43	// engineViolations parses one Go source and returns one line per forbidden use:
44	// a selector on the docker or engine package outside its list, a string
45	// literal that is a forbidden verb, or an import of os/exec.
46	func engineViolations(filename string, src any) ([]string, error) {
47		fset := token.NewFileSet()
48		f, err := parser.ParseFile(fset, filename, src, 0)
49		if err != nil {
50			return nil, err
51		}
52		allowed := map[string][]string{} // local package name -> allowed selectors
53		var out []string
54		report := func(pos token.Pos, what string) {
55			out = append(out, filepath.Base(filename)+":"+strconv.Itoa(fset.Position(pos).Line)+": "+what)
56		}
57		for _, imp := range f.Imports {
58			path, _ := strconv.Unquote(imp.Path.Value)
59			local := filepath.Base(path)
60			if imp.Name != nil {
61				local = imp.Name.Name
62			}
63			switch path {
64			case dockerImportPath:
65				allowed[local] = allowedDockerUses
66			case engineImportPath:
67				allowed[local] = allowedEngineUses
68			case "os/exec":
69				report(imp.Pos(), "imports os/exec")
70			}
71		}
72		ast.Inspect(f, func(n ast.Node) bool {
73			switch x := n.(type) {
74			case *ast.SelectorExpr:
75				id, ok := x.X.(*ast.Ident)
76				if !ok {
77					return true
78				}
79				if list, isPkg := allowed[id.Name]; isPkg && !slices.Contains(list, x.Sel.Name) {
80					report(x.Pos(), id.Name+"."+x.Sel.Name+" is not on the read-only list")
81				}
82			case *ast.BasicLit:
83				if x.Kind != token.STRING {
84					return true
85				}
86				if s, err := strconv.Unquote(x.Value); err == nil && slices.Contains(forbiddenVerbs, strings.TrimSpace(s)) {
87					report(x.Pos(), "string literal "+x.Value+" is an engine verb that changes a container")
88				}
89			}
90			return true
91		})
92		return out, nil
93	}
94	
95	func TestPathTabCallsOnlyReadOnlyEngineFunctions(t *testing.T) {
96		files, err := filepath.Glob("*.go")
97		if err != nil || len(files) == 0 {
98			t.Fatalf("no source file found (err %v)", err)
99		}
100		scanned := 0
101		for _, file := range files {
102			if strings.HasSuffix(file, "_test.go") {
103				continue
104			}
105			raw, err := os.ReadFile(file)
106			if err != nil {
107				t.Fatal(err)
108			}
109			got, err := engineViolations(file, raw)
110			if err != nil {
111				t.Fatalf("%s: %v", file, err)
112			}
113			for _, v := range got {
114				t.Errorf("%s", v)
115			}
116			scanned++
117		}
118		if scanned < 10 {
119			t.Fatalf("scanned %d files: the guard would pass on nothing", scanned)
120		}
121	}
122	
123	// The detector itself: it fails on each kind of forbidden use, an alias does not
124	// hide one, and clean code passes.
125	func TestEngineViolationsDetectsForbiddenUses(t *testing.T) {
126		const head = "package netdiag\nimport (\n\t\"github.com/anthnel/devdesk/internal/docker\"\n\teng \"github.com/anthnel/devdesk/internal/engine\"\n)\n"
127		cases := []struct {
128			name string
129			body string
130			want int
131		}{
132			{"clean", "var _ = docker.ListContainersContext\nvar _ docker.Container\nvar _ = docker.IsContainerID\nvar _ = eng.Current", 0},
133			{"docker function outside the list", "var _ = docker.StartContainer", 1},
134			{"docker exec", "var _ = docker.ExecInContainer", 1},
135			{"engine function outside the list", "var _ = eng.Run", 1},
136			{"verb as an argument", "var _ = []string{\"container\", \"start\", \"abc\"}", 1},
137			{"exec verb", "var _ = []string{\"exec\", \"-it\"}", 1},
138			{"run verb", "var _ = \"run\"", 1},
139			{"cp verb", "var _ = \"cp\"", 1},
140			{"attach verb", "var _ = \"attach\"", 1},
141			{"read verbs are fine", "var _ = []string{\"ps\", \"info\", \"container\", \"inspect\"}", 0},
142		}
143		for _, tc := range cases {
144			t.Run(tc.name, func(t *testing.T) {
145				got, err := engineViolations("synthetic.go", head+tc.body+"\n")
146				if err != nil {
147					t.Fatal(err)
148				}
149				if len(got) != tc.want {
150					t.Errorf("violations = %v, want %d", got, tc.want)
151				}
152			})
153		}
154		got, err := engineViolations("synthetic.go", "package netdiag\nimport \"os/exec\"\nvar _ = exec.Command\n")
155		if err != nil || len(got) != 1 {
156			t.Errorf("os/exec import: violations %v, err %v, want one", got, err)
157		}
158	}
