1	package netdiag
2	
3	import (
4		"errors"
5		"fmt"
6		"net"
7		"net/netip"
8		"strings"
9		"testing"
10	
11		tea "charm.land/bubbletea/v2"
12		"github.com/charmbracelet/x/ansi"
13	
14		"github.com/anthnel/devdesk/internal/docker"
15		"github.com/anthnel/devdesk/internal/netcheck"
16		"github.com/anthnel/devdesk/internal/nettrace"
17		"github.com/anthnel/devdesk/internal/ui/testutil"
18	)
19	
20	// DEVDESK-330 step 7: the container, network and trace rows at 80 and 60
21	// columns, with names that do not fit, wide characters and IPv6.
22	
23	const (
24		// addressCellsAt80 is the Address column at 80 columns (plan H5): 78 minus
25		// four paddings of two, minus Hop 3, Step 11 and RTT 9.
26		addressCellsAt80 = 47
27	
28		longCtrName = "payments-gateway-worker-eu-west-1-blue-green-0123456789" // 55 cells
29		longNetName = "customer-facing-backend-overlay-network-01"              // 41 cells
30		cjkCtrName  = "日本語のコンテナ名前日本語のコンテナ名前日本語"                                 // 24 wide runes, 48 cells
31	)
32	
33	// layoutCase is one container as the engine described it.
34	type layoutCase struct {
35		name string
36		ctr  docker.ContainerNetworking
37	}
38	
39	func layoutCases() []layoutCase {
40		v4 := func(name, net string) docker.ContainerNetworking {
41			return docker.ContainerNetworking{
42				Name: name, Running: true, Mode: net,
43				Networks: []docker.EndpointNetwork{{
44					Name: net, IPv4: netip.MustParseAddr("172.18.0.5"), Gateway: netip.MustParseAddr("172.18.0.1"),
45				}},
46			}
47		}
48		v6 := v4(longCtrName, longNetName)
49		v6.Networks[0].IPv4 = netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:7334")
50		v6.Networks[0].Gateway = netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:1")
51		return []layoutCase{
52			{"long ascii names", v4(longCtrName, longNetName)},
53			{"cjk names", v4(cjkCtrName, "ネットワーク名前ネットワーク名前")},
54			{"ipv6", v6},
55			{"host mode", docker.ContainerNetworking{Name: longCtrName, Running: true, Mode: "host", Networks: []docker.EndpointNetwork{{Name: "host"}}}},
56		}
57	}
58	
59	// containerRun is longRun with a container source: the 30-hop trace of longHost
60	// from the container described by lc, in the given state. With picker set, the
61	// selector is open over a 40-entry list afterwards.
62	func containerRun(t *testing.T, width, height int, state string, lc layoutCase, picker bool) *Model {
63		t.Helper()
64		captureLog(t)
65		m := onPathTab(t)
66		m = feed(t, m, tea.WindowSizeMsg{Width: width, Height: height})
67		src := pathSource{ID: idWeb, Name: lc.ctr.Name}
68		m.pathModel.source = src
69		m = feed(t, m, testutil.Type(longHost)...)
70		m = feed(t, m, testutil.Key("enter"))
71		gen := m.pathModel.gen
72	
73		route := netcheck.RouteHop{Interface: longIface, Source: net.ParseIP("192.168.1.21"), Gateway: net.ParseIP("192.168.1.1")}
74		m = feed(t, m, pathResolvedMsg{gen: gen, addr: netip.MustParseAddr("198.51.100.30"), route: route, source: src, ctr: lc.ctr})
75		var hops []nettrace.Hop
76		for ttl := 1; ttl <= manyHops; ttl++ {
77			h := nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("2001:db8:85a3:0:0:8a2e:370:7334")}
78			if ttl == manyHops {
79				h = nettrace.Hop{TTL: ttl, Kind: nettrace.HopTarget, Addr: netip.MustParseAddr("198.51.100.30")}
80			}
81			hops = append(hops, h)
82			m = feed(t, m, pathHopMsg{gen: gen, hop: h})
83		}
84		switch state {
85		case "done":
86			m = feed(t, m, pathDoneMsg{gen: gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached, Hops: hops}})
87		case "canceled":
88			m = feed(t, m, testutil.Key("esc"))
89		}
90		if picker {
91			var rows []docker.Container
92			for i := range 40 {
93				rows = append(rows, docker.Container{
94					ID: fmt.Sprintf("%012x", i+1), Name: fmt.Sprintf("container-%02d-%s", i, strings.Repeat("日", 20)),
95					Image: "registry.example.com/team/image", State: "running",
96				})
97			}
98			m.pathModel.engine = (&fakeEngine{psRows: rows}).engine()
99			m, cmd := step(t, m, testutil.Key("ctrl+o"))
100			m = feed(t, m, testutil.Msg(cmd))
101			if !m.pathModel.pickerOpen() {
102				t.Fatalf("state %s: the selector did not open", state)
103			}
104			return m
105		}
106		return m
107	}
108	
109	// Every body line is exactly width-2 cells, no escape sequence is cut, with and
110	// without the selector. The selector cannot open while a trace runs (refused,
111	// see TestPathSourceKeyIsRefusedWithAReason), so running is covered without it.
112	func TestPathContainerRowsFitTheTerminalWidth(t *testing.T) {
113		for _, lc := range layoutCases() {
114			for _, width := range []int{80, 60} {
115				for _, state := range []string{"running", "done", "canceled"} {
116					for _, picker := range []bool{false, true} {
117						if picker && state == "running" {
118							continue
119						}
120						name := fmt.Sprintf("%s/%d/%s/picker=%v", lc.name, width, state, picker)
121						t.Run(name, func(t *testing.T) {
122							m := containerRun(t, width, 24, state, lc, picker)
123							body := m.Render()
124							for i, line := range strings.Split(body, "\n") {
125								if w := ansi.StringWidth(line); w != width-2 {
126									t.Errorf("body line %d is %d cells wide, want %d: %q", i, w, width-2, ansi.Strip(line))
127								}
128							}
129							if got := m.pathModel.table.RenderedWidth(); got != width-2 {
130								t.Errorf("RenderedWidth = %d, want %d (Rule 116)", got, width-2)
131							}
132							plain := ansi.Strip(body)
133							if strings.ContainsRune(plain, '\x1b') || strings.Contains(plain, "38;2;") {
134								t.Errorf("an escape sequence survives the strip (cut sequence):\n%q", plain)
135							}
136							if picker {
137								return // the selector covers the first rows by design
138							}
139							if !strings.Contains(plain, "container") || !strings.Contains(plain, "network") {
140								t.Errorf("the container and network rows are missing:\n%s", plain)
141							}
142							if !strings.Contains(plain, "…") {
143								t.Errorf("no truncation mark although names exceed the column:\n%s", plain)
144							}
145						})
146					}
147				}
148			}
149		}
150	}
151	
152	// The trace row, in full at 80 columns, truncated at 60 (the Address column is
153	// 27 cells there).
154	func TestPathTraceRowAtTheTwoWidths(t *testing.T) {
155		lc := layoutCases()[0]
156		for _, state := range []string{"running", "done", "canceled"} {
157			t.Run(state, func(t *testing.T) {
158				at80 := ansi.Strip(containerRun(t, 80, 24, state, lc, false).Render())
159				if !strings.Contains(at80, textTraceFromHost) {
160					t.Errorf("80 columns: %q is not whole:\n%s", textTraceFromHost, at80)
161				}
162				at60 := ansi.Strip(containerRun(t, 60, 24, state, lc, false).Render())
163				if strings.Contains(at60, textTraceFromHost) || !strings.Contains(at60, "from this machine") {
164					t.Errorf("60 columns: want the trace text cut with a mark:\n%s", at60)
165				}
166			})
167		}
168	}
169	
